/*
[演算法邏輯說明]
尋找給定範圍內 [t1, t2] 的「數位質數」(Digit Primes)。
數位質數是指：該數本身是質數，且其各位數位之和也是質數。
1. 使用篩法 (Sieve of Eratosthenes) 預先找出 1,000,000 以內的所有質數。
2. 遍歷 1 到 1,000,000，檢查每個數是否為數位質數。
   - 如果 i 是質數，計算其數位和 sum。
   - 如果 sum 也是質數，則 i 是數位質數。
3. 使用前綴和 (Prefix Sum) 陣列 count[i]，記錄從 1 到 i 的數位質數總數。
4. 對於每個查詢 [t1, t2]，其結果即為 count[t2] - count[t1-1]。
5. 由於輸入量大 (最多 500,000 個查詢)，需使用快速輸入輸出 (scanf/printf)。
*/

#include <cstdio>
#include <vector>

using namespace std;

const int MAX = 1000000;
bool is_prime[MAX];
int digit_prime_count[MAX];

void sieve() {
    for (int i = 0; i < MAX; ++i) is_prime[i] = true;
    is_prime[0] = is_prime[1] = false;
    for (int p = 2; p * p < MAX; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i < MAX; i += p)
                is_prime[i] = false;
        }
    }
}

int sumDigits(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

int main() {
    sieve();
    int current = 0;
    for (int i = 1; i < MAX; ++i) {
        if (is_prime[i] && is_prime[sumDigits(i)]) {
            current++;
        }
        digit_prime_count[i] = current;
    }

    int n;
    if (scanf("%d", &n) != 1) return 0;
    while (n--) {
        int t1, t2;
        scanf("%d %d", &t1, &t2);
        printf("%d\n", digit_prime_count[t2] - digit_prime_count[t1 - 1]);
    }
    return 0;
}
